import android.Manifest;import android.app.Activity;import android.bluetooth.BluetoothAdapter;import android.bluetooth.le.AdvertiseCallback;import android.bluetooth.le.AdvertiseData;import android.bluetooth.le.AdvertiseSettings;import android.bluetooth.le.BluetoothLeAdvertiser;import android.bluetooth.le.BluetoothLeScanner;import android.bluetooth.le.ScanCallback;import android.bluetooth.le.ScanResult;import android.content.Context;import android.content.Intent;import android.content.SharedPreferences;import android.content.pm.PackageManager;import android.graphics.Color;import android.net.wifi.WifiManager;import android.os.Build;import android.os.Bundle;import android.os.Handler;import android.os.Looper;import android.os.SystemClock;import android.widget.Button;import android.widget.LinearLayout;import android.widget.ScrollView;import android.widget.TextView;import org.json.JSONArray;import org.json.JSONException;import org.json.JSONObject;import java.net.DatagramPacket;import java.net.InetAddress;import java.net.InetSocketAddress;import java.net.MulticastSocket;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.ArrayList;import java.util.Collections;import java.util.List;import java.util.Locale;import java.util.Map;import java.util.UUID;import java.util.concurrent.ConcurrentHashMap;import java.util.concurrent.ConcurrentLinkedDeque;
public class MainActivity extends Activity{
 private static final int PORT=47777,PROTOCOL=2,MANUFACTURER_ID=0x05F1;private static final String GROUP="239.255.77.77",SESSION="body-finder-lab";private final Handler ui=new Handler(Looper.getMainLooper());private final Map<String,Peer> peers=new ConcurrentHashMap<>();private final Map<String,ConcurrentLinkedDeque<Sample>> rssiWindows=new ConcurrentHashMap<>();private volatile boolean running=true,scanning=false,bleScanning=false,bleAdvertising=false;private volatile Double baseline=null,sigma=null;private volatile String bleDetail="BLE not started";private String nodeId;private TextView status;private MulticastSocket socket;private WifiManager.MulticastLock multicastLock;private BluetoothLeScanner bleScanner;private BluetoothLeAdvertiser bleAdvertiser;private ScanCallback scanCallback;private AdvertiseCallback advertiseCallback;private static class Peer{final String json;final long seen;Peer(String j,long s){json=j;seen=s;}}private static class Sample{final int rssi,tx;final long ms;Sample(int r,int t,long m){rssi=r;tx=t;ms=m;}}
 @Override public void onCreate(Bundle b){super.onCreate(b);SharedPreferences sp=getSharedPreferences("bf",MODE_PRIVATE);nodeId=sp.getString("nodeIdV2",null);if(nodeId==null){nodeId="legacy-"+UUID.randomUUID();sp.edit().putString("nodeIdV2",nodeId).apply();}requestPermissionsIfNeeded();buildUi();startBle();startFabric();}
 private boolean granted(String p){return Build.VERSION.SDK_INT<23||checkSelfPermission(p)==PackageManager.PERMISSION_GRANTED;}private void requestPermissionsIfNeeded(){if(Build.VERSION.SDK_INT<23)return;ArrayList<String> p=new ArrayList<>();if(!granted(Manifest.permission.ACCESS_FINE_LOCATION))p.add(Manifest.permission.ACCESS_FINE_LOCATION);if(Build.VERSION.SDK_INT>=31){for(String x:new String[]{Manifest.permission.BLUETOOTH_SCAN,Manifest.permission.BLUETOOTH_CONNECT,Manifest.permission.BLUETOOTH_ADVERTISE})if(!granted(x))p.add(x);}if(Build.VERSION.SDK_INT>=33&&!granted("android.permission.NEARBY_WIFI_DEVICES"))p.add("android.permission.NEARBY_WIFI_DEVICES");if(!p.isEmpty())requestPermissions(p.toArray(new String[0]),42);}@Override public void onRequestPermissionsResult(int requestCode,String[] permissions,int[] grantResults){super.onRequestPermissionsResult(requestCode,permissions,grantResults);if(requestCode==42)startBle();}
 private TextView text(String value,int size){TextView v=new TextView(this);v.setText(value);v.setTextColor(Color.rgb(225,245,248));v.setTextSize(size);v.setPadding(0,8,0,8);return v;}private void buildUi(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(24,24,24,24);box.setBackgroundColor(Color.rgb(7,16,21));box.addView(text("Body Finder – RuView LEGACY AUTO-GEOMETRY NODE",20));TextView w=text("EXPERIMENTAL BLE/RSSI NODE — NOT VALIDATED FOR RESCUE USE",11);w.setTextColor(Color.rgb(255,180,84));box.addView(w);box.addView(text("No sensor coordinates are entered here. This fallback node advertises/scans Body Finder BLE packets and reports live pairwise range observations with conservative uncertainty.",12));Button cal=new Button(this);cal.setText("CALIBRATE EMPTY SCENE (8s)");cal.setOnClickListener(v->calibrate(cal));box.addView(cal);Button scan=new Button(this);scan.setText("START HUMAN-EVIDENCE SCAN");scan.setOnClickListener(v->{scanning=!scanning;scan.setText(scanning?"STOP HUMAN-EVIDENCE SCAN":"START HUMAN-EVIDENCE SCAN");});box.addView(scan);Button share=new Button(this);share.setText("SHARE SNAPSHOT JSON");share.setOnClickListener(v->shareSnapshot());box.addView(share);status=text("Starting automatic fabric…",12);status.setTextIsSelectable(true);box.addView(status);ScrollView sc=new ScrollView(this);sc.addView(box);setContentView(sc);}
 @SuppressWarnings("deprecation")private Double rssi(){try{WifiManager wm=(WifiManager)getApplicationContext().getSystemService(Context.WIFI_SERVICE);if(wm==null||!wm.isWifiEnabled())return null;int v=wm.getConnectionInfo().getRssi();return(v>-127&&v<=0)?(double)v:null;}catch(Throwable t){return null;}}private JSONObject probe(String state,String detail)throws JSONException{return new JSONObject().put("state",state).put("detail",detail);}private JSONObject capabilities()throws JSONException{return new JSONObject().put("wifi_rssi",probe(rssi()!=null?"WORKING":"PROBE_FAILED","legacy connected-link Wi-Fi RSSI; human evidence only, never inter-node distance")).put("wifi_rtt",probe("UNSUPPORTED","legacy adapter does not expose RTT")).put("ble_peer_ranging",probe(bleScanning?"WORKING_DEGRADED":"SUPPORTED_UNVERIFIED",bleDetail+"; BLE RSSI model uses large sigma")).put("csi",probe("UNSUPPORTED","RSSI is never labeled CSI")).put("udp_fabric",probe("WORKING_DEGRADED","multicast/broadcast requires field verification")).put("compute",probe("WORKING_DEGRADED","legacy Android sensor node; geometry is solved by full-app/native compute peers"));}
 private String bleIdentity(){try{byte[] d=MessageDigest.getInstance("SHA-256").digest(nodeId.getBytes(StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();for(int i=0;i<8;i++)s.append(String.format(Locale.US,"%02x",d[i]&0xff));return s.toString();}catch(Throwable t){String x=nodeId.replace("-","");return x.substring(0,Math.min(16,x.length()));}}private byte[] blePayload(){byte[] out=new byte[10];out[0]=0x42;out[1]=0x46;String id=bleIdentity();for(int i=0;i<8;i++)out[i+2]=(byte)Integer.parseInt(id.substring(i*2,i*2+2),16);return out;}private String payloadIdentity(byte[] data){if(data==null||data.length<10||data[0]!=(byte)0x42||data[1]!=(byte)0x46)return null;StringBuilder s=new StringBuilder();for(int i=2;i<10;i++)s.append(String.format(Locale.US,"%02x",data[i]&0xff));return s.toString();}
 private synchronized void startBle(){stopBle();try{BluetoothAdapter a=BluetoothAdapter.getDefaultAdapter();if(a==null||!a.isEnabled()){bleDetail="Bluetooth disabled/unavailable";return;}if(Build.VERSION.SDK_INT>=31&&(!granted(Manifest.permission.BLUETOOTH_SCAN)||!granted(Manifest.permission.BLUETOOTH_ADVERTISE))){bleDetail="Bluetooth permission required";return;}bleScanner=a.getBluetoothLeScanner();bleAdvertiser=a.getBluetoothLeAdvertiser();if(bleScanner==null){bleDetail="BLE scanner unavailable";return;}scanCallback=new ScanCallback(){@Override public void onScanResult(int type,ScanResult result){recordScan(result);}@Override public void onBatchScanResults(List<ScanResult> results){for(ScanResult r:results)recordScan(r);}@Override public void onScanFailed(int error){bleScanning=false;bleDetail="BLE scan failed code="+error;}};bleScanner.startScan(scanCallback);bleScanning=true;if(bleAdvertiser!=null){advertiseCallback=new AdvertiseCallback(){@Override public void onStartSuccess(AdvertiseSettings s){bleAdvertising=true;bleDetail="BLE scan + advertisement active";}@Override public void onStartFailure(int e){bleAdvertising=false;bleDetail="BLE scan active; advertisement failed code="+e;}};AdvertiseSettings settings=new AdvertiseSettings.Builder().setAdvertiseMode(AdvertiseSettings.ADVERTISE_MODE_LOW_LATENCY).setTxPowerLevel(AdvertiseSettings.ADVERTISE_TX_POWER_MEDIUM).setConnectable(false).build();AdvertiseData data=new AdvertiseData.Builder().addManufacturerData(MANUFACTURER_ID,blePayload()).setIncludeTxPowerLevel(true).build();bleAdvertiser.startAdvertising(settings,data,advertiseCallback);}else bleDetail="BLE scan active; advertising unsupported";}catch(Throwable t){bleDetail="BLE start failed: "+t.getClass().getSimpleName();}}private void stopBle(){try{if(bleScanner!=null&&scanCallback!=null)bleScanner.stopScan(scanCallback);}catch(Throwable ignored){}try{if(bleAdvertiser!=null&&advertiseCallback!=null)bleAdvertiser.stopAdvertising(advertiseCallback);}catch(Throwable ignored){}bleScanner=null;bleAdvertiser=null;scanCallback=null;advertiseCallback=null;bleScanning=false;bleAdvertising=false;rssiWindows.clear();}
 private void recordScan(ScanResult r){try{String id=payloadIdentity(r.getScanRecord()==null?null:r.getScanRecord().getManufacturerSpecificData(MANUFACTURER_ID));if(id==null||id.equals(bleIdentity()))return;int tx=r.getScanRecord()!=null&&r.getScanRecord().getTxPowerLevel()>=-100&&r.getScanRecord().getTxPowerLevel()<=20?r.getScanRecord().getTxPowerLevel():-59;long now=System.currentTimeMillis();ConcurrentLinkedDeque<Sample> q=rssiWindows.get(id);if(q==null){ConcurrentLinkedDeque<Sample> created=new ConcurrentLinkedDeque<>();ConcurrentLinkedDeque<Sample> old=rssiWindows.putIfAbsent(id,created);q=old==null?created:old;}q.addLast(new Sample(r.getRssi(),tx,now));while(q.size()>21)q.pollFirst();while(q.peekFirst()!=null&&now-q.peekFirst().ms>8000)q.pollFirst();}catch(Throwable ignored){}}private double median(List<Double> values){Collections.sort(values);int n=values.size();return n%2==0?(values.get(n/2-1)+values.get(n/2))/2.0:values.get(n/2);}
 private JSONArray ranges(){JSONArray out=new JSONArray();long now=System.currentTimeMillis(),mono=SystemClock.elapsedRealtimeNanos();for(Peer p:peers.values())try{JSONObject peer=new JSONObject(p.json);String bid=peer.optString("ble_identity","");if(bid.length()==0||"null".equals(bid))continue;ConcurrentLinkedDeque<Sample> q=rssiWindows.get(bid);if(q==null)continue;ArrayList<Sample> fresh=new ArrayList<>();for(Sample s:q)if(now-s.ms<=5000)fresh.add(s);if(fresh.size()<3)continue;ArrayList<Double> rs=new ArrayList<>(),ts=new ArrayList<>();for(Sample s:fresh){rs.add((double)s.rssi);ts.add((double)s.tx);}double mr=median(rs),mt=median(ts),n=2.2,d=Math.pow(10.0,(mt-mr)/(10.0*n));d=Math.max(.2,Math.min(30,d));double sig=Math.max(1.5,d*.75);out.put(new JSONObject().put("session_id",SESSION).put("observer_node_id",nodeId).put("peer_node_id",peer.optString("node_id")).put("technology","BLE_RSSI").put("monotonic_ns",mono).put("distance_m",d).put("distance_sigma_m",sig).put("azimuth_deg",JSONObject.NULL).put("azimuth_sigma_deg",JSONObject.NULL).put("elevation_deg",JSONObject.NULL).put("elevation_sigma_deg",JSONObject.NULL).put("rssi_dbm",mr).put("quality","LOW").put("source_detail","Legacy live BLE RSSI; median "+fresh.size()+" samples; conservative path-loss model; not RTT/UWB/CSI"));}catch(Throwable ignored){}return out;}
 private JSONObject advertisement()throws JSONException{JSONObject j=new JSONObject();j.put("protocol_version",PROTOCOL);j.put("session_id",SESSION);j.put("node_id",nodeId);j.put("display_name",Build.MODEL+" legacy");j.put("platform","android-legacy");j.put("monotonic_ns",SystemClock.elapsedRealtimeNanos());j.put("coordinator_score",.52);j.put("capabilities",capabilities());Double r=rssi();j.put("rssi_dbm",r==null?JSONObject.NULL:r);j.put("baseline_rssi_dbm",baseline==null?JSONObject.NULL:baseline);j.put("baseline_sigma_db",sigma==null?JSONObject.NULL:sigma);j.put("position",JSONObject.NULL);j.put("scanning",scanning&&baseline!=null);j.put("ble_identity",bleIdentity());j.put("ranges",ranges());j.put("manual_geometry_override",false);return j;}
 private void calibrate(final Button b){scanning=false;b.setEnabled(false);status.setText("CALIBRATING: keep target zone empty…");new Thread(()->{double sum=0,sum2=0;int n=0;for(int i=0;i<32;i++){Double r=rssi();if(r!=null){sum+=r;sum2+=r*r;n++;}try{Thread.sleep(250);}catch(InterruptedException ignored){}}if(n>=8){double m=sum/n;baseline=m;sigma=Math.max(1,Math.sqrt(Math.max(0,sum2/n-m*m)));}ui.post(()->{b.setEnabled(true);refreshStatus();});},"bf-calibrate").start();}private void expirePeers(){long now=System.currentTimeMillis();for(Map.Entry<String,Peer> e:peers.entrySet())if(now-e.getValue().seen>5000)peers.remove(e.getKey(),e.getValue());}private void refreshStatus(){expirePeers();int edgeCount=ranges().length();status.setText(String.format(Locale.US,"node=%s\nmodel=%s API=%d\nRSSI=%s dBm\nbaseline=%s sigma=%s\ngeometry=AUTO ONLY\nBLE=%s\nrange edges=%d\nhuman scan=%s\npeers=%d\nCSI=UNSUPPORTED\nnetwork=OPEN/UNTRUSTED",nodeId,Build.MODEL,Build.VERSION.SDK_INT,String.valueOf(rssi()),String.valueOf(baseline),String.valueOf(sigma),bleDetail,edgeCount,String.valueOf(scanning),peers.size()));}
 private void startFabric(){new Thread(()->{try{WifiManager wm=(WifiManager)getApplicationContext().getSystemService(Context.WIFI_SERVICE);if(wm!=null){multicastLock=wm.createMulticastLock("body-finder-legacy-v2");multicastLock.setReferenceCounted(false);multicastLock.acquire();}MulticastSocket s=new MulticastSocket(null);socket=s;s.setReuseAddress(true);s.setBroadcast(true);s.bind(new InetSocketAddress(PORT));s.setSoTimeout(250);InetAddress group=InetAddress.getByName(GROUP);try{s.joinGroup(group);}catch(Throwable ignored){}InetAddress broad=InetAddress.getByName("255.255.255.255");byte[] buf=new byte[65507];long next=0;while(running){long now=System.currentTimeMillis();if(now>=next){byte[] bytes=advertisement().toString().getBytes(StandardCharsets.UTF_8);try{s.send(new DatagramPacket(bytes,bytes.length,group,PORT));}catch(Throwable ignored){}try{s.send(new DatagramPacket(bytes,bytes.length,broad,PORT));}catch(Throwable ignored){}next=now+800;ui.post(this::refreshStatus);}try{DatagramPacket packet=new DatagramPacket(buf,buf.length);s.receive(packet);String txt=new String(packet.getData(),packet.getOffset(),packet.getLength(),StandardCharsets.UTF_8);JSONObject o=new JSONObject(txt);String id=o.optString("node_id");if(o.optInt("protocol_version")==PROTOCOL&&SESSION.equals(o.optString("session_id"))&&!id.equals(nodeId)&&id.length()>0)peers.put(id,new Peer(txt,System.currentTimeMillis()));}catch(java.net.SocketTimeoutException ignored){}catch(Throwable ignored){}}}catch(Throwable t){ui.post(()->status.setText("Fabric error: "+t));}},"bf-fabric-v2").start();}private void shareSnapshot(){try{String txt=new JSONObject().put("report_version",3).put("protocol_version",PROTOCOL).put("truth","LIVE_LEGACY_BLE_AND_WIFI_RSSI__AUTO_GEOMETRY_INPUT_ONLY").put("manual_geometry_override",false).put("advertisement",advertisement()).put("peer_count",peers.size()).toString(2);Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,txt);startActivity(Intent.createChooser(i,"Body Finder result"));}catch(Throwable t){status.setText(String.valueOf(t));}}@Override protected void onDestroy(){running=false;stopBle();try{if(socket!=null)socket.close();}catch(Throwable ignored){}try{if(multicastLock!=null&&multicastLock.isHeld())multicastLock.release();}catch(Throwable ignored){}super.onDestroy();}
}
